('00000000-0000-0000-0000-000000000000', 'Müssen Unternehmen im Anwendersupport Datenschutzgesetze einhalten?', 2, '[{"text": "Ja", "correct": true, "because": "Schutz personenbezogener Daten"}, {"text": "Nein", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die DSGVO ein Gesetz, das den Anwendersupport betrifft?', 2, '[{"text": "Ja", "correct": true, "because": "Regelt Datenverarbeitung"}, {"text": "Nein", "correct": false, "because": "DSGVO ist relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Verstöße gegen Informationssicherheitsgesetze im Anwendersupport Strafen nach sich ziehen?', 2, '[{"text": "Ja", "correct": true, "because": "Gesetzliche Sanktionen"}, {"text": "Nein", "correct": false, "because": "Strafen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das BDSG nur für große Unternehmen im Anwendersupport relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Datenverarbeiter"}, {"text": "Ja", "correct": false, "because": "Unabhängig von Größe"}]'),
